#define MAX_GROUPS 10000
#define SEATS 17

typedef struct {
    int arrive;   // arrival time in minutes from 11:00
    int size;     // group size
    int stay;     // dining duration
} Group;

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        Group groups[MAX_GROUPS];
        int gcount = 0;

        /* Read groups until EOF for this dataset is not specified in the statement fragment,
           so we use the standard AOJ-style format:
           after n, groups are given and terminated by a line "0 0 0". */
        while (scanf("%d %d %d", &groups[gcount].arrive, &groups[gcount].size, &groups[gcount].stay) == 3) {
            if (groups[gcount].arrive == 0 && groups[gcount].size == 0 && groups[gcount].stay == 0) break;
            gcount++;
        }

        int seat_until[SEATS];
        for (int i = 0; i < SEATS; i++) seat_until[i] = 0;

        int answer = 0;

        for (int i = 0; i < gcount; i++) {
            int t = groups[i].arrive;

            while (1) {
                int freecnt = 0;
                for (int s = 0; s < SEATS; s++) {
                    if (seat_until[s] <= t) freecnt++;
                }

                if (freecnt >= groups[i].size) {
                    int need = groups[i].size;
                    for (int s = 0; s < SEATS && need > 0; s++) {
                        if (seat_until[s] <= t) {
                            seat_until[s] = t + groups[i].stay;
                            need--;
                        }
                    }
                    if (i + 1 == n) answer = t - groups[i].arrive;
                    break;
                }

                int next_t = 1 << 30;
                for (int s = 0; s < SEATS; s++) {
                    if (seat_until[s] > t && seat_until[s] < next_t) next_t = seat_until[s];
                }
                t = next_t;
            }
        }

        printf("%d\n", answer);
    }

    return 0;
}

import java.util.Scanner;

public class RamenWaitingTime {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            System.out.println(simulate(n));
        }
        sc.close();
    }

    static int simulate(int groupIndex) {
        // There are 17 seats
        int[] seats = new int[17]; // 0 means empty, >0 means occupied until that time
        int[] arrivalTimes = new int[100]; // arrival time for each group (0-indexed)
        int[] groupSizes = new int[100];
        int[] durations = new int[100];

        // Precompute group properties
        int currentTime = 0;
        for (int i = 0; i < 100; i++) {
            arrivalTimes[i] = currentTime;
            if (i % 5 == 0) {
                groupSizes[i] = 2;
            } else if (i % 5 == 1) {
                groupSizes[i] = 5;
            } else if (i % 5 == 2) {
                groupSizes[i] = 2;
            } else if (i % 5 == 3) {
                groupSizes[i] = 3;
            } else { // i % 5 == 4
                groupSizes[i] = 4;
            }

            if (i % 2 == 0) {
                durations[i] = 17 * (i % 2 + 3) + 3; // for even i
            } else {
                durations[i] = 17 * (i % 2 + 3) + 3; // same formula, since (i%2+3) = 4 for odd
            }
            // Simplify: duration = 17 * ((i%2)+3) + 3
            durations[i] = 17 * ((i % 2) + 3) + 3;

            currentTime += 5; // groups arrive every 5 minutes
        }

        // Now simulate group by group
        int[] waitTime = new int[100];
        for (int g = 0; g <= groupIndex; g++) {
            int arrive = arrivalTimes[g];
            int size = groupSizes[g];
            int eatTime = durations[g];

            // Free seats that are done by arrival time
            for (int s = 0; s < 17; s++) {
                if (seats[s] <= arrive) {
                    seats[s] = 0;
                }
            }

            // Find earliest time all can sit
            int startTime = arrive;
            while (true) {
                // Free seats up to startTime
                for (int s = 0; s < 17; s++) {
                    if (seats[s] <= startTime) {
                        seats[s] = 0;
                    }
                }
                int emptyCount = 0;
                for (int s = 0; s < 17; s++) {
                    if (seats[s] == 0) emptyCount++;
                }
                if (emptyCount >= size) {
                    break;
                }
                // Move to next minute
                startTime++;
            }

            // Seat the group
            int seated = 0;
            for (int s = 0; s < 17 && seated < size; s++) {
                if (seats[s] == 0) {
                    seats[s] = startTime + eatTime;
                    seated++;
                }
            }

            waitTime[g] = startTime - arrive;
        }

        return waitTime[groupIndex];
    }
}

