public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Group {
        int arrival;
        int size;
        int duration;

        Group(int arrival, int size, int duration) {
            this.arrival = arrival;
            this.size = size;
            this.duration = duration;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }

            if (n < 0) break;

            Group[] groups = new Group[100];
            for (int i = 0; i < 100; i++) {
                int t = fs.nextInt();
                int s = fs.nextInt();
                int d = fs.nextInt();
                groups[i] = new Group(t, s, d);
            }

            int ans = simulate(groups, n);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static int simulate(Group[] groups, int target) {
        int seats = 17;

        // Min-heap of leaving times for currently seated customers
        PriorityQueue<Integer> leaving = new PriorityQueue<>();

        // Queue of waiting groups: stores indices of groups waiting in order
        ArrayDeque<Integer> waitQ = new ArrayDeque<>();

        int[] startTime = new int[groups.length];

        for (int i = 0; i < groups.length; i++) {
            int now = groups[i].arrival;

            // Free seats up to current arrival time
            while (!leaving.isEmpty() && leaving.peek() <= now) {
                leaving.poll();
                seats++;
            }

            // Seat waiting groups as much as possible before processing current arrival
            boolean progressed = true;
            while (progressed && !waitQ.isEmpty()) {
                progressed = false;
                int idx = waitQ.peekFirst();
                if (groups[idx].size <= seats) {
                    waitQ.pollFirst();
                    seats -= groups[idx].size;
                    startTime[idx] = now;
                    for (int k = 0; k < groups[idx].size; k++) {
                        leaving.add(now + groups[idx].duration);
                    }
                    progressed = true;
                }
            }

            // Current group arrives
            if (waitQ.isEmpty() && groups[i].size <= seats) {
                seats -= groups[i].size;
                startTime[i] = now;
                for (int k = 0; k < groups[i].size; k++) {
                    leaving.add(now + groups[i].duration);
                }
            } else {
                waitQ.addLast(i);
            }
        }

        // Process remaining waiting groups after last arrival
        while (!waitQ.isEmpty()) {
            int nextTime = leaving.peek();

            while (!leaving.isEmpty() && leaving.peek() <= nextTime) {
                leaving.poll();
                seats++;
            }

            boolean progressed = true;
            while (progressed && !waitQ.isEmpty()) {
                progressed = false;
                int idx = waitQ.peekFirst();
                if (groups[idx].size <= seats) {
                    waitQ.pollFirst();
                    seats -= groups[idx].size;
                    startTime[idx] = nextTime;
                    for (int k = 0; k < groups[idx].size; k++) {
                        leaving.add(nextTime + groups[idx].duration);
                    }
                    progressed = true;
                }
            }
        }

        return startTime[target] - groups[target].arrival;
    }
}

