struct Group {
    int arrive, size, dine;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<Group> groups;
    int a, b, c;

    // Read all groups until EOF
    while (cin >> a >> b >> c) {
        groups.push_back({a, b, c});
    }

    const int SEATS = 17;
    vector<int> answer;
    int occupied = 0;

    // Min-heap of (leaving_time, group_size)
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;

    for (int i = 0; i < (int)groups.size(); i++) {
        int t = groups[i].arrive;
        int sz = groups[i].size;
        int d = groups[i].dine;

        // Free seats for groups that have already left by arrival time t
        while (!pq.empty() && pq.top().first <= t) {
            occupied -= pq.top().second;
            pq.pop();
        }

        int start = t;

        // Wait until enough seats become available
        while (occupied + sz > SEATS) {
            start = pq.top().first;

            while (!pq.empty() && pq.top().first <= start) {
                occupied -= pq.top().second;
                pq.pop();
            }
        }

        answer.push_back(start - t);
        occupied += sz;
        pq.push({start + d, sz});
    }

    for (int x : answer) {
        cout << x << '\n';
    }

    return 0;
}
